CREATE TABLE purchase_requests(id UUID PRIMARY KEY,requester_name VARCHAR(150) NOT NULL,requester_email VARCHAR(255) NOT NULL,concept VARCHAR(200) NOT NULL,description VARCHAR(2000) NOT NULL,amount NUMERIC(19,2) NOT NULL CHECK(amount>0),cost_center VARCHAR(100) NOT NULL,status VARCHAR(20) NOT NULL CHECK(status IN('PENDIENTE','APROBADA','RECHAZADA')),decision_comment VARCHAR(1000),created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE INDEX idx_purchase_requests_status ON purchase_requests(status); CREATE INDEX idx_purchase_requests_created ON purchase_requests(created_at DESC);
